import java.io.*;

public class Main {
    static class Picker {
        Picker(int[] w) {
            // Write your solution here
        }

        int pick(long r) {
            // Write your solution here
            return 0;
        }
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        int[] w = new int[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            w[i] = (int) in.nval;
        }
        Picker picker = new Picker(w);
        in.nextToken();
        int q = (int) in.nval;
        StringBuilder sb = new StringBuilder();
        for (int j = 0; j < q; j++) {
            in.nextToken();
            sb.append(picker.pick((long) in.nval)).append('\n');
        }
        System.out.print(sb);
    }
}
